#!/usr/bin/env python3
"""Fetch Paul Graham essays and generate an audiobook MP3."""

from __future__ import annotations

import json
import os
import re
import subprocess
import time
import urllib.request
from html.parser import HTMLParser
import html as html_lib

ESSAYS = [
    {
        "title": "Do Things that Don't Scale",
        "url": "https://paulgraham.com/ds.html",
    },
    {
        "title": "Founder Mode",
        "url": "https://paulgraham.com/foundermode.html",
    },
]

OUTPUT_PATH = "/root/audiobook.mp3"


class PGContentParser(HTMLParser):
    """Extract text inside the first <font size=2 face=verdana> block."""

    def __init__(self) -> None:
        super().__init__()
        self.capture = False
        self.depth = 0
        self.in_script = False
        self.in_style = False
        self.parts: list[str] = []

    def handle_starttag(self, tag, attrs):
        if tag in ("script", "style"):
            self.in_script = True
            return
        if tag == "font":
            attrs_dict = {k.lower(): v for k, v in attrs}
            if not self.capture:
                if attrs_dict.get("size") == "2" and attrs_dict.get("face", "").lower() == "verdana":
                    self.capture = True
                    self.depth = 1
                    return
            else:
                self.depth += 1
        if self.capture and tag in ("p", "br", "tr", "li", "table"):
            self.parts.append("\n")

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        if tag == "font" and self.capture:
            self.depth -= 1
            if self.depth <= 0:
                self.capture = False
                self.depth = 0

    def handle_endtag(self, tag):
        if tag in ("script", "style"):
            self.in_script = False
            return
        if tag == "font" and self.capture:
            self.depth -= 1
            if self.depth <= 0:
                self.capture = False
                self.depth = 0
        if self.capture and tag in ("p", "br", "tr", "li", "table"):
            self.parts.append("\n")

    def handle_data(self, data):
        if self.capture and not self.in_script and not self.in_style:
            self.parts.append(data)

    def handle_entityref(self, name):
        if self.capture:
            self.parts.append(html_lib.unescape(f"&{name};"))

    def handle_charref(self, name):
        if self.capture:
            self.parts.append(html_lib.unescape(f"&#{name};"))


def fetch_html(url: str) -> str:
    req = urllib.request.Request(
        url,
        headers={
            "User-Agent": "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36",
        },
    )
    with urllib.request.urlopen(req, timeout=30) as resp:
        content = resp.read()
    return content.decode("utf-8", errors="ignore")


def extract_text(html: str) -> str:
    parser = PGContentParser()
    parser.feed(html)
    text = "".join(parser.parts)
    if not text.strip():
        # Fallback: strip tags crudely if parsing failed
        text = re.sub(r"<script[^>]*>.*?</script>", " ", html, flags=re.DOTALL | re.IGNORECASE)
        text = re.sub(r"<style[^>]*>.*?</style>", " ", text, flags=re.DOTALL | re.IGNORECASE)
        text = re.sub(r"<[^>]+>", " ", text)
    return text


def clean_text(text: str) -> str:
    text = text.replace("\r", "\n")
    text = re.sub(r"[\t\f\v ]+", " ", text)
    text = re.sub(r"\n\s*\n+", "\n\n", text)
    text = re.sub(r" *\n *", "\n", text)
    text = text.strip()

    # Remove YC promo block if present
    text = re.sub(
        r"\bWant to start a startup\?\s*Get funded by Y Combinator\.\s*",
        "",
        text,
        flags=re.IGNORECASE,
    )

    # Remove footnote markers like [1]
    text = re.sub(r"\s*\[\d+\]", "", text)

    # Normalize punctuation to ASCII
    replacements = {
        "—": "--",
        "–": "-",
        "“": '"',
        "”": '"',
        "‘": "'",
        "’": "'",
        "…": "...",
    }
    for src, dst in replacements.items():
        text = text.replace(src, dst)

    # Remove any remaining non-ASCII characters
    text = text.encode("ascii", errors="ignore").decode("ascii")

    # Normalize whitespace again
    text = re.sub(r"[ \t]+", " ", text)
    text = re.sub(r"\n\s*\n+", "\n\n", text)
    text = re.sub(r" *\n *", "\n", text)
    return text.strip()


def chunk_text(text: str, max_chars: int = 3800) -> list[str]:
    # Collapse whitespace for chunking
    normalized = re.sub(r"\s+", " ", text).strip()
    if not normalized:
        return []

    sentences = re.split(r"(?<=[.!?])\s+", normalized)
    chunks: list[str] = []
    current = ""

    for sentence in sentences:
        if not sentence:
            continue
        if len(sentence) > max_chars:
            # Hard split long sentence
            start = 0
            while start < len(sentence):
                end = min(start + max_chars, len(sentence))
                chunk = sentence[start:end].strip()
                if chunk:
                    if current:
                        chunks.append(current.strip())
                        current = ""
                    chunks.append(chunk)
                start = end
            continue

        if len(current) + len(sentence) + 1 <= max_chars:
            current = f"{current} {sentence}".strip()
        else:
            if current:
                chunks.append(current.strip())
            current = sentence.strip()

    if current:
        chunks.append(current.strip())
    return chunks


def openai_tts(chunks: list[str], output_path: str) -> bool:
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        return False

    audio_files: list[str] = []
    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/tts_chunk_{i:03d}.mp3"
        payload = {
            "model": "tts-1",
            "input": chunk,
            "voice": "onyx",
            "response_format": "mp3",
        }
        data = json.dumps(payload).encode("utf-8")
        req = urllib.request.Request(
            "https://api.openai.com/v1/audio/speech",
            data=data,
            headers={
                "Authorization": f"Bearer {api_key}",
                "Content-Type": "application/json",
            },
        )
        try:
            with urllib.request.urlopen(req, timeout=60) as resp:
                audio = resp.read()
        except Exception as exc:
            print(f"OpenAI TTS failed on chunk {i}: {exc}")
            return False

        with open(chunk_file, "wb") as f:
            f.write(audio)
        audio_files.append(chunk_file)
        time.sleep(0.2)

    return concatenate_audio(audio_files, output_path)


def elevenlabs_tts(chunks: list[str], output_path: str) -> bool:
    api_key = os.environ.get("ELEVENLABS_API_KEY")
    if not api_key:
        return False

    voice_id = "21m00Tcm4TlvDq8ikWAM"  # Rachel
    audio_files: list[str] = []

    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/tts_chunk_{i:03d}.mp3"
        payload = {
            "text": chunk,
            "model_id": "eleven_turbo_v2_5",
            "voice_settings": {"stability": 0.5, "similarity_boost": 0.75},
        }
        data = json.dumps(payload).encode("utf-8")
        req = urllib.request.Request(
            f"https://api.elevenlabs.io/v1/text-to-speech/{voice_id}",
            data=data,
            headers={
                "xi-api-key": api_key,
                "Content-Type": "application/json",
            },
        )
        try:
            with urllib.request.urlopen(req, timeout=60) as resp:
                audio = resp.read()
        except Exception as exc:
            print(f"ElevenLabs TTS failed on chunk {i}: {exc}")
            return False

        with open(chunk_file, "wb") as f:
            f.write(audio)
        audio_files.append(chunk_file)
        time.sleep(0.2)

    return concatenate_audio(audio_files, output_path)


def gtts_tts(chunks: list[str], output_path: str) -> bool:
    try:
        from gtts import gTTS  # type: ignore
    except Exception as exc:
        print(f"gTTS not available: {exc}")
        return False

    audio_files: list[str] = []
    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/tts_chunk_{i:03d}.mp3"
        tts = gTTS(text=chunk, lang="en", slow=False)
        tts.save(chunk_file)
        audio_files.append(chunk_file)

    return concatenate_audio(audio_files, output_path)


def concatenate_audio(audio_files: list[str], output_path: str) -> bool:
    if not audio_files:
        return False

    list_file = "/tmp/audio_list.txt"
    with open(list_file, "w", encoding="utf-8") as f:
        for audio_file in audio_files:
            f.write(f"file '{audio_file}'\n")

    result = subprocess.run(
        ["ffmpeg", "-y", "-f", "concat", "-safe", "0", "-i", list_file, "-c", "copy", output_path],
        capture_output=True,
        text=True,
    )

    # Cleanup temp files
    for audio_file in audio_files:
        try:
            os.unlink(audio_file)
        except FileNotFoundError:
            pass
    try:
        os.unlink(list_file)
    except FileNotFoundError:
        pass

    if result.returncode != 0:
        print("ffmpeg concat failed:")
        print(result.stderr)
        return False

    return True


def build_text() -> str:
    combined_parts: list[str] = []
    for essay in ESSAYS:
        print(f"Fetching {essay['title']}...")
        html = fetch_html(essay["url"])
        raw_text = extract_text(html)
        cleaned = clean_text(raw_text)
        if len(cleaned) < 1000:
            print(f"Warning: extracted text for {essay['title']} seems short ({len(cleaned)} chars)")
        combined_parts.append(f"Essay: {essay['title']}. By Paul Graham.\n\n{cleaned}\n\nEnd of essay.\n")
    return "\n".join(combined_parts).strip()


def main() -> int:
    full_text = build_text()
    print(f"Total text length: {len(full_text)} characters")

    chunks = chunk_text(full_text, max_chars=3800)
    if not chunks:
        print("No text to convert.")
        return 1

    print(f"Total chunks: {len(chunks)}")

    # Try providers in priority order
    if elevenlabs_tts(chunks, OUTPUT_PATH):
        print(f"Audiobook written to {OUTPUT_PATH} via ElevenLabs")
        return 0
    if openai_tts(chunks, OUTPUT_PATH):
        print(f"Audiobook written to {OUTPUT_PATH} via OpenAI TTS")
        return 0

    print("Falling back to gTTS (if available)...")
    if gtts_tts(chunks, OUTPUT_PATH):
        print(f"Audiobook written to {OUTPUT_PATH} via gTTS")
        return 0

    print("All TTS providers failed.")
    return 1


if __name__ == "__main__":
    raise SystemExit(main())
